const KEY='orion-blue-workspace-v1';const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export function calculateRisk({balance,risk,stop,value,whole}){const a=[balance,risk,stop,value].map(v=>Number(v));if([balance,risk,stop,value].some(v=>v===''||v==null)||a.some(v=>!Number.isFinite(v)||v<=0)||a[1]>100)return null;const budget=a[0]*a[1]/100,perUnit=a[2]*a[3],raw=budget/perUnit,units=whole?Math.floor(raw):raw;if(![budget,perUnit,raw,units,units*perUnit].every(Number.isFinite))return null;return {budget,perUnit,units,actual:units*perUnit};}
export function journalMetrics(rows){const rated=rows.filter(r=>r.status==='closed'&&r.result!==null&&r.result!==''&&Number.isFinite(Number(r.result)));return{count:rows.length,rated:rated.length,average:rated.length?rated.reduce((s,r)=>s+Number(r.result),0)/rated.length:null,lessons:rows.filter(r=>r.lesson?.trim()).length};}
export function createWorkspace({show,notify,tone,onChange}){
 let store={sessions:{},journal:[],risk:{balance:'',risk:'',stop:'',value:'',whole:false},timer:{duration:900,remaining:900,end:null}},storageError=false;
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&typeof s==='object'){if(s.sessions&&typeof s.sessions==='object')store.sessions=s.sessions;if(Array.isArray(s.journal))store.journal=s.journal.filter(e=>e&&typeof e.id==='string'&&typeof e.date==='string');if(s.risk&&typeof s.risk==='object')store.risk={...store.risk,...s.risk};if(s.timer&&Number.isFinite(s.timer.remaining)&&s.timer.remaining>=0)store.timer=s.timer;}}catch{storageError=true;}
 let tab='session',query='',filter='all',editor=null,undo=null;
 function save(){try{localStorage.setItem(KEY,JSON.stringify(store));storageError=false;}catch{storageError=true;}const el=document.querySelector('[data-save-status]');if(el)el.textContent=storageError?'Not saved — browser storage is unavailable. Export a backup.':'Saved on this browser';onChange?.();return !storageError;}
 function current(){const k=day();store.sessions[k]??={checks:[false,false,false],note:'',noTrade:false};return store.sessions[k];}
 const n=(v,d=2)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
 function summary(){const s=current();return{prepared:s.noTrade||s.checks.every(Boolean),checks:s.checks.filter(Boolean).length,risk:!!calculateRisk(store.risk),reviews:store.journal.length};}
 function shell(content){return `<div class="tool-shell"><span class="eyebrow">PRIVATE / LOCAL WORKSPACE</span><h2 id="dialog-title">${tab==='session'?'Prepare your session':tab==='risk'?'Position-risk calculator':'Your trade review journal'}</h2><div class="tool-tabs">${[['session','Session plan'],['risk','Risk calculator'],['journal','Trade journal']].map(([v,t])=>`<button data-tool-tab="${v}" aria-pressed="${tab===v}" class="${tab===v?'active':''}">${t}</button>`).join('')}</div>${content}<div class="tool-footer"><span data-save-status>${storageError?'Not saved — browser storage is unavailable.':'Saved on this browser'}</span><button class="text-button" data-work="export">Export local data</button></div><p class="small-note">Local tools do not award Points or place trades. Data stays in this browser and is not synced to your trading account.</p></div>`;}
 function session(){const s=current(),complete=s.noTrade||s.checks.every(Boolean);return `<div class="session-grid"><section><div class="section-head"><h3>${day()}</h3><span class="pill ${complete?'success':''}">${complete?'Preparation complete':s.checks.filter(Boolean).length+' / 3 checks'}</span></div><div class="plan-checks">${['Reviewed my trading plan','Checked scheduled events','Set my personal risk limits'].map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${s.checks[i]?'checked':''}><span>${t}</span></label>`).join('')}</div><label class="no-trade"><input type="checkbox" data-no-trade ${s.noTrade?'checked':''}>No trading planned today</label><label class="field"><span>My session intention</span><textarea data-session-note rows="4" maxlength="1000" placeholder="One thing I want to do well today…">${safe(s.note)}</textarea></label><p class="small-note">Taking a planned day off counts as preparation. No trading is required.</p></section><section class="focus-box"><span class="eyebrow">FOCUS TIMER</span><div class="timer-ring"><strong data-timer-text></strong><span>${store.timer.end?'IN PROGRESS':'READY WHEN YOU ARE'}</span></div><div class="timer-options">${[5,15,25].map(m=>`<button class="${store.timer.duration===m*60?'active':''}" data-minutes="${m}" ${store.timer.end?'disabled':''}>${m} min</button>`).join('')}</div><div class="timer-buttons"><button class="btn primary" data-work="timer">${store.timer.end?'Pause':store.timer.remaining<store.timer.duration?'Resume':'Start focus'}</button><button class="btn" data-work="reset-timer">Reset</button></div><p class="small-note">An optional timer for preparation or review.</p></section></div>`;}
 function risk(){const r=store.risk;return `<div class="risk-layout"><form class="risk-form" autocomplete="off"><p class="dialog-copy">Use your own balance, risk limit and instrument values.</p>${[['balance','Account balance','In your account currency'],['risk','Risk percentage','Your chosen percentage, greater than 0 and up to 100'],['stop','Stop distance','In price points'],['value','Value per price point per unit','Money in the same account currency']].map(([k,t,d])=>`<label class="field"><span>${t}</span><input type="number" inputmode="decimal" step="any" min="0" ${k==='risk'?'max="100"':''} data-risk="${k}" value="${safe(r[k])}" placeholder="Enter value"><small>${d}</small></label>`).join('')}<label class="check-label"><input type="checkbox" data-risk="whole" ${r.whole?'checked':''}>Whole units only — round down</label></form><div class="risk-output" aria-live="polite">${riskResult()}</div></div><p class="small-note">Estimate only. Excludes fees, slippage and instrument sizing restrictions. No recommended risk level is assumed.</p>`;}
 function riskResult(){const r=calculateRisk(store.risk);return r?`<span class="eyebrow">ESTIMATED POSITION SIZE</span><strong class="risk-units">${n(r.units,4)}<span>units</span></strong><div class="risk-breakdown"><div><span>Risk budget</span><b>${n(r.budget)}</b></div><div><span>Risk per unit</span><b>${n(r.perUnit)}</b></div><div><span>Calculated position risk</span><b>${n(r.actual)}</b></div></div><p>Values use your account currency.</p>${r.units===0?'<p class="form-error">Your budget does not cover one whole unit.</p>':''}`:`<span class="eyebrow">POSITION ESTIMATE</span><strong class="risk-units">—<span>units</span></strong><p>Enter four valid positive numbers to calculate. Risk percentage must be no more than 100.</p><div class="formula">Balance × Risk %<br><span>÷ (Stop distance × Point value)</span></div>`;}
 function rows(){return store.journal.filter(r=>(filter==='all'||r.status===filter)&&(r.instrument+' '+r.tag+' '+r.lesson+' '+r.date).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));}
 function journal(){const list=rows(),m=journalMetrics(list);return `<div class="journal-summary"><div><strong>${m.count}</strong><span>Reviews</span></div><div><strong>${m.average===null?'—':(m.average>=0?'+':'')+n(m.average)+'R'}</strong><span>Average · ${m.rated} rated closed</span></div><div><strong>${m.lessons}</strong><span>Written lessons</span></div></div><div class="journal-toolbar"><input type="search" data-journal-search placeholder="Search instrument, date or lesson" value="${safe(query)}" aria-label="Search trade reviews"><select data-journal-filter aria-label="Review status"><option value="all" ${filter==='all'?'selected':''}>All reviews</option><option value="closed" ${filter==='closed'?'selected':''}>Closed</option><option value="open" ${filter==='open'?'selected':''}>Open</option></select><button class="btn primary" data-work="new-review">Add review</button></div>${undo?'<div class="undo-bar">Review removed. <button data-work="undo">Undo</button></div>':''}<div class="journal-list">${list.length?list.map(r=>`<article class="journal-entry"><div><span class="pill">${safe(r.status)}</span><time>${safe(r.date)}</time><strong>${safe(r.instrument||'Untitled trade')}</strong><span>${safe(r.tag)}</span><b>${r.result===null?'Unrated':(Number(r.result)>0?'+':'')+n(r.result)+'R'}</b></div><p>${safe(r.lesson||'No lesson recorded yet.')}</p><button class="text-button" data-edit="${safe(r.id)}">Edit review</button></article>`).join(''):'<div class="empty"><span>01 / REFLECT</span><h3>Every session can teach you something.</h3><p>Add a trade review to start your private journal.</p></div>'}</div><p class="small-note">R is the recorded result relative to your initial risk. Blank is unrated; 0R is a break-even result. Average includes rated, closed reviews only.</p>`;}
 function editForm(){const r=editor;return `<form id="review-form"><div class="section-head"><h3>${r.id?'Edit review':'New trade review'}</h3><button type="button" class="text-button" data-work="cancel-review">Back to journal</button></div><div class="form-grid"><label class="field"><span>Trade date</span><input type="date" name="date" required value="${safe(r.date)}"></label><label class="field"><span>Instrument</span><input name="instrument" maxlength="60" placeholder="e.g. EUR/USD" value="${safe(r.instrument)}"></label><label class="field"><span>Status</span><select name="status"><option value="closed" ${r.status==='closed'?'selected':''}>Closed</option><option value="open" ${r.status==='open'?'selected':''}>Open</option></select></label><label class="field"><span>Result in R (optional)</span><input type="number" step="any" name="result" placeholder="e.g. 1.5 or -1" value="${r.result===null?'':safe(r.result)}"></label></div><label class="field"><span>Setup / tag (optional)</span><input name="tag" maxlength="80" value="${safe(r.tag)}" placeholder="Your own setup label"></label><label class="field"><span>What did you learn?</span><textarea rows="4" name="lesson" maxlength="2000" placeholder="What worked, what changed, and what to repeat…">${safe(r.lesson)}</textarea></label><p id="review-error" class="form-error" role="status"></p><div class="form-actions"><button class="btn primary" type="submit">Save review</button>${r.id?`<button type="button" class="text-button danger" data-delete="${safe(r.id)}">Delete review</button>`:''}</div></form>`;}
 function open(t=tab,keepEditor=false){tab=t;if(!keepEditor)editor=null;show(shell(tab==='session'?session():tab==='risk'?risk():editor?editForm():journal()),'workspace-dialog');tick();}
 function tick(){const t=store.timer;if(t.end){t.remaining=Math.max(0,Math.ceil((t.end-Date.now())/1000));if(t.remaining===0){t.end=null;save();notify('Focus complete. Take a moment to reflect.');tone(true);if(document.querySelector('.workspace-dialog .timer-buttons'))open('session');}}const el=document.querySelector('[data-timer-text]');if(el)el.textContent=String(Math.floor(t.remaining/60)).padStart(2,'0')+':'+String(t.remaining%60).padStart(2,'0');}
 setInterval(tick,1000);
 function download(){const b=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...store},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='orion-local-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Local workspace export prepared.');}
 function click(b){if(b.dataset.toolTab){open(b.dataset.toolTab);document.querySelector(`[data-tool-tab="${tab}"]`).focus();return true;}if(b.dataset.minutes){store.timer={duration:Number(b.dataset.minutes)*60,remaining:Number(b.dataset.minutes)*60,end:null};save();open('session');return true;}if(b.dataset.edit){editor={...store.journal.find(r=>r.id===b.dataset.edit)};open('journal',true);return true;}if(b.dataset.delete){undo=store.journal.find(r=>r.id===b.dataset.delete);store.journal=store.journal.filter(r=>r.id!==b.dataset.delete);save();open('journal');return true;}if(!b.dataset.work)return false;switch(b.dataset.work){case'export':download();break;case'timer':tick();if(store.timer.end)store.timer.end=null;else{if(!store.timer.remaining)store.timer.remaining=store.timer.duration;store.timer.end=Date.now()+store.timer.remaining*1000;}save();open('session');break;case'reset-timer':store.timer.remaining=store.timer.duration;store.timer.end=null;save();open('session');break;case'new-review':editor={id:null,date:day(),instrument:'',status:'closed',result:null,tag:'',lesson:''};open('journal',true);break;case'cancel-review':open('journal');break;case'undo':if(undo){store.journal.push(undo);undo=null;save();open('journal');}break;}return true;}
 function input(e){const t=e.target;if(t.matches('[data-check]')){current().checks[Number(t.dataset.check)]=t.checked;save();open('session');document.querySelector(`[data-check="${t.dataset.check}"]`).focus();tone();return;}if(t.matches('[data-no-trade]')){current().noTrade=t.checked;save();open('session');document.querySelector('[data-no-trade]').focus();return;}if(t.matches('[data-session-note]')){current().note=t.value;save();return;}if(t.dataset.risk){store.risk[t.dataset.risk]=t.type==='checkbox'?t.checked:t.value;save();document.querySelector('.risk-output').innerHTML=riskResult();return;}if(t.matches('[data-journal-search]')){query=t.value;const sel=[t.selectionStart,t.selectionEnd];open('journal');const f=document.querySelector('[data-journal-search]');f.focus();f.setSelectionRange(...sel);return;}if(t.matches('[data-journal-filter]')){filter=t.value;open('journal');document.querySelector('[data-journal-filter]').focus();}}
 function submit(e){if(e.target.id!=='review-form')return false;e.preventDefault();const f=new FormData(e.target),raw=String(f.get('result')).trim(),result=raw===''?null:Number(raw);if(result!==null&&!Number.isFinite(result)){document.querySelector('#review-error').textContent='Use a valid signed number for the result.';return true;}const rec={id:editor.id||crypto.randomUUID(),date:String(f.get('date')),instrument:String(f.get('instrument')).trim(),status:String(f.get('status')),result,tag:String(f.get('tag')).trim(),lesson:String(f.get('lesson')).trim()};if(!rec.date){document.querySelector('#review-error').textContent='Choose a trade date.';return true;}const i=store.journal.findIndex(r=>r.id===rec.id);if(i<0)store.journal.push(rec);else store.journal[i]=rec;save();open('journal');notify(storageError?'Review kept for now. Export a backup.':'Review saved on this browser.');tone(true);return true;}
 return {open,click,input,submit,summary};
}
